local flow = require("luastd.flow")
local runtest = require("luastd_test").runtest

-- kotlin: kotlinx-coroutines-core/common/test/flow/sharing/SharingStartedWhileSubscribedTest.kt@1.11.0
describe("SharingStartedWhileSubscribedTest", function ()
    -- adapted: compare policy equality directly; Lua has no overridable hash
    -- function for table keys, so Kotlin's HashMap hash-code consistency check
    -- cannot be represented.
    it("testEqualsAndHashcode", runtest(function ()
        local params = { 0, 1, 10, 100, 213, 9007199254740991 }
        local make = flow.sharing_started.while_subscribed
        for _, stop in ipairs(params) do
            for _, expiration in ipairs(params) do
                local other_stop = stop == 0 and 1 or 0
                local other_expiration = expiration == 0 and 1 or 0
                assert.is_true(make(stop, expiration) == make(stop, expiration))
                assert.is_false(make(stop, expiration) == make(other_stop, expiration))
                assert.is_false(make(stop, expiration) == make(stop, other_expiration))
            end
        end
    end))

    -- adapted: the Lua policy accepts millisecond numbers directly and has no
    -- Duration type; use the largest exactly representable finite millisecond
    -- value and infinity for replay expiration. Stop timeout must remain finite.
    it("testDurationParams", runtest(function ()
        local make = flow.sharing_started.while_subscribed
        assert.is_true(make(0) == make(0, math.huge))
        assert.is_true(make(10) == make(10, math.huge))
        assert.is_true(make(1000) == make(1000, math.huge))
        assert.is_true(make(9007199254740991) == make(9007199254740991, math.huge))
        assert.is_true(make(0, 0) == make(0, 0))
        assert.is_true(make(0, 3) == make(0, 3))
        assert.is_true(make(0, 7000) == make(0, 7000))
        assert.is_true(make(0, math.huge) == make(0, math.huge))
    end))

    -- defer: Flow:share_in always starts eagerly and does not accept a
    -- SharingStarted policy, so it cannot test unsubscribe-driven restarts.
    pending("testShouldRestart")

    -- defer: Flow:share_in has no stop-timeout, replay-expiration, or
